  "centuryDisplay": "XVe-XVIe s.",
  "centuryNumeric": 1436,
  "domain": "espace_sacre",
  "artifactType": "Plafond, Voûte & Coupole",
  "title": "Coupole autoportante à double coque de Brunelleschi et fresques du Jugement dernier du Duomo de Florence",
  "site": "Cathédrale Santa Maria del Fiore / Duomo (Florence, Toscane, Italie)",
  "originSite": "Florence (Toscane, Italie)",
